                                if (same > 0 && minSameVal <= 5) return "交一张同类型牌";
                                if (diff >= 2 && minDiffVal <= 9) return "弃两张不同类型牌";
                                // 杀且无闪且残血：优先交/弃保命
                                if (isSha && shan === 0 && victim.hp + (victim.hujia || 0) <= 2) {
                                    if (same > 0) return "交一张同类型牌";
                                    if (diff >= 2) return "弃两张不同类型牌";
                                }
                                // 能防住且交/弃代价高 → 硬吃
                                if (canStop && minSameVal > 6 && minDiffVal > 10) return "不可响应，你出杀+1";
                                if (same > 0) return "交一张同类型牌";
                                if (diff >= 2) return "弃两张不同类型牌";
                                return "不可响应，你出杀+1";
