            // 无双剑姬·利刃
            "csh_liren": {
                audio: "ext:池子魔将/audio/skill/csh_liren.mp3",
                enable: "phaseUse",
                usable: 1,
                filterTarget(card, player, target) {
                    if (target === player) return false;
                    // 非主公
                    if (target.identity === "zhu" || target.isZhu) return false;
                    return true;
                },
                selectTarget: 1,
                async content(event, trigger, player) {
                    lib.cshPlayExt("ext:池子魔将/audio/skill/csh_liren.mp3")
                    const target = event.targets[0];
                    await target.damage(1, player);
                    if (!target.isIn()) return;
                    // 与「受伤目标」的上家或下家换座 → 彬坐过去
                    const neighbors = [target.getPrevious(), target.getNext()].filter(p => p && p.isIn() && p !== target && p !== player);
                    if (!neighbors.length) return;
                    const { bool, targets } = await player
                        .chooseTarget("利刃：选择与" + get.translation(target) + "的上家或下家交换座位（你坐过去）", true, (card, p, t) => neighbors.includes(t))
                        .set("ai", t => {
                            // 优先换到更靠近敌人的位置 / 对友军威胁小的位置
                            return -get.attitude(player, t) + (get.distance(t, target) === 1 ? 1 : 0);
                        })
                        .forResult();
                    if (bool && targets && targets[0]) {
                        const other = targets[0];
                        try {
                            // 彬 与 目标上家/下家 互换座位
                            if (typeof game.swapSeat === "function") {
                                game.swapSeat(player, other);
                            }
                            game.log(player, "与", other, "交换了座位");
                        } catch (e) {
                            console.log("[池子魔将] 利刃换座失败", e);
                        }
                    }
                },
                ai: {
                    order: 7,
                    result: {
                        target(player, target) {
                            const att = get.attitude(player, target);
                            if (att > 0) return -0.4;
                            if (att === 0) return -1;
                            let score = -1.8;
                            if (target.hp <= 1) score -= 2.2;
                            else if (target.hp <= 2) score -= 0.8;
                            if (target.hujia) score -= 0.2;
                            return score;
                        },
                        player(player, target) {
                            const damage = get.damageEffect(target, player, player);
                            if (target && target.hp <= 1 && get.attitude(player, target) < 0) return damage + 2;
                            return damage;
                        },
                    },
                },
            },
