            "csh_poyin": {
                audio: ["dbquedi",2],
                trigger: {
                    player: "shaBegin",
                },
                // 发动动画：仅使用 effect/csh_wenyang_quedi_banner.mp4（大爱逆流同管线），不用限定技动画
                direct: true,
                filter(event, player) {
                    return player.countCards("he") > 0;
                },
                content() {
                    "step 0";
                    var target = trigger.target;
                    var foe = get.attitude(player, target) < 0;
                    var isHuman = player.isMine() || player.isOnline();
                    // AI 效果预评估（只读，供 AI 弃牌决策与择优使用；真人玩家不受影响）
                    var scores = [0, 0, 0, 0];
                    // 效果0：弃置目标所有牌
                    if (foe) {
                        var cards0 = target.getCards("hej");
                        var sum0 = 0;
                        for (var i0 = 0; i0 < cards0.length; i0++) {
                            sum0 += get.value(cards0[i0], target);
                        }
                        scores[0] = Math.min(9, sum0 * 0.7);
                    } else {
                        scores[0] = -2;
                    }
                    // 效果1：造成2点雷属性伤害（护甲每点抵挡1点伤害）
                    var lost = Math.min(target.hp, Math.max(0, 2 - target.hujia));
                    if (foe) {
                        var dmgEff = get.damageEffect(target, player, player, "thunder");
                        scores[1] = lost * 2.2;
                        if (dmgEff <= 0) scores[1] = -scores[1];
                        if (lost >= target.hp && target.hp > 0 && dmgEff > 0) scores[1] += 8;
                    } else {
                        scores[1] = -lost * 2.2;
                    }
                    // 效果2：体力上限+1、获得1点护甲（无回血）
                    var s2 = player.maxHp >= 6 ? 0.8 : 1.5;
                    if (player.hujia > 0) {
                        s2 += 0.8;
                    } else {
                        s2 += 1.4;
                    }
                    if (player.hp <= 2) s2 += 0.6;
                    // 局势加权：主公或局面宽松时敢于慢慢发育；明显逆风时优先即时收益
                    if (player.identity == "zhu") s2 += 0.8;
                    var teamHp = 0;
                    var foeHp = 0;
                    for (var p of game.players) {
                        if (!p.isAlive() || p == player) continue;
                        var att0 = get.attitude(player, p);
                        if (att0 > 0) {
                            teamHp += p.hp;
                        } else if (att0 < 0) {
                            foeHp += p.hp;
                        }
                    }
                    if (teamHp > 0 && teamHp >= foeHp * 1.3) {
                        s2 += 0.8;
                    } else if (foeHp > 0 && foeHp >= teamHp * 1.3) {
                        s2 -= 0.8;
                    }
                    scores[2] = s2;
                    // 效果3：翻面（跳过目标下回合；目标已翻面时则相反）
                    var weight = 1 + target.countCards("hej") * 0.15;
                    if (target.isTurnedOver()) {
                        scores[3] = foe ? -3 : 2.6 * weight;
                    } else {
                        scores[3] = (foe ? 1 : -1) * 2.6 * weight;
                    }
                    var idx = 0;
                    for (var j = 1; j < 4; j++) {
                        if (scores[j] > scores[idx]) idx = j;
                    }
                    var best = scores[idx];
                    event._cshPoyinAI = {
                        foe: foe,
                        isHuman: isHuman,
                        idx: idx,
                        best: best,
                    };
                    var next = player.chooseToDiscard("he", get.prompt("csh_poyin", target));
                    next.ai = function (card) {
                        if (!foe || best <= 0) return 0;
                        return Math.max(0, best * 0.9 + 4 - get.value(card));
                    };
                    next.logSkill = ["csh_poyin", target];
                    "step 1";
                    if (!result.bool) {
                        event.finish();
                        return;
                    }
                    event._poyinOk = true;
                    // 先播完整动画，再结算效果（对齐大爱逆流：broadcast + await 时长）
                    try {
                        game.broadcastAll(function () {
                            try {
                                if (lib.cshShoushaFx) lib.cshShoushaFx.play("quedi", null);
                            } catch (e0) {}
                        });
                    } catch (e1) {}
                    "step 2";
                    if (!event._poyinOk) return;
                    // 暂停至动画播完（默认 2.8s，可在 _dur.quedi 调整）
                    var waitMs = 2800;
                    try {
                        if (lib.cshShoushaFx && lib.cshShoushaFx._dur && lib.cshShoushaFx._dur.quedi) waitMs = lib.cshShoushaFx._dur.quedi;
                    } catch (e2) {}
                    game.pause();
                    setTimeout(function () {
                        try {
                            game.resume();
                        } catch (e3) {}
                    }, waitMs);
                    "step 3";
                    if (!event._poyinOk) return;
                    var target = trigger.target;
                    if (!target || !target.isIn()) return;
                    var ai = event._cshPoyinAI || {};
                    var applyIdx;
                    if (!ai.isHuman && ai.best > 0) {
                        applyIdx = ai.idx;
                    } else {
                        applyIdx = Math.floor(Math.random() * 4);
                    }
                    switch (applyIdx) {
                        case 0:
                            target.discard(target.getCards("hej"));
                            break;
                        case 1:
                            target.damage(2, "thunder");
                            break;
                        case 2:
                            player.gainMaxHp();
                            player.changeHujia();
                            break;
                        case 3:
                            target.turnOver();
                            break;
                    }
                },
                ai: {
                    threaten: 2.2,
                    expose: 0.3,
                    // 有牌时可弃置发动破音，鼓励对敌出杀
                    effect: {
                        player(card, player, target) {
                            if (!card || get.name(card) !== "sha") return;
                            if (!target || get.attitude(player, target) >= 0) return;
                            if (player.countCards("he") > 0) return [1, 1.5];
                        },
                    },
                },
                _priority: 0,
                skill_id: "csh_poyin",
            },
