            "csh_jiaomeng": {
                audio: ["tamo",2],
                enable: "phaseUse",
                usable: 3,
                filterTarget: function(card,player,target){
                    return Math.abs(target.countCards('h')-player.countCards('h'))<=1;
                },
                content: function(){
                    player.swapHandcards(target);
                },
                // 交换价值评估（联机安全：无闭包，挂技能对象供各端 AI 本地调用）
                // _advantage = 目标手牌对我与其自身的价值之和 - 我的手牌对我与其自身的价值之和
                // 对敌人：即"我方增益 + 敌方减益"的实力差变化；对队友：即全队总价值变化
                _advantage: function(player,target){
                    var tgCards=target.getCards('h');
                    var myCards=player.getCards('h');
                    var num=0;
                    for(var i=0;i<tgCards.length;i++){
                        num+=get.value(tgCards[i],player);
                        num+=get.value(tgCards[i],target);
                    }
                    for(var i=0;i<myCards.length;i++){
                        num-=get.value(myCards[i],player);
                        num-=get.value(myCards[i],target);
                    }
                    return num;
                },
                ai: {
                    order: function(){
                        var player=_status.event.player;
                        if(player.hasCard(function(card){
                            return get.value(card,player)>=8;
                        })){
                            return 0;
                        }
                        var nh=player.countCards('h');
                        if(game.hasPlayer(function(current){
                            if(current==player||Math.abs(current.countCards('h')-nh)>1) return false;
                            return lib.skill.csh_jiaomeng._advantage(player,current)>3;
                        })){
                            return 9;
                        }
                        return 1;
                    },
                    result: {
                        player: function(player,target){
                            var att=get.attitude(player,target);
                            var adv=lib.skill.csh_jiaomeng._advantage(player,target);
                            if(att>0){
                                // 队友：牌流向更能发挥价值的角色（我残血留杀无用、满血队友拿杀可用等）
                                return adv>3?1:0;
                            }
                            // 敌人：持桃不换出（喂桃风险），除非优势巨大
                            if(player.countCards('h',{name:'tao'})>0&&adv<8) return 0;
                            if(adv<=0) return 0;
                            var num=adv/4;
                            // 毒陷阱：敌 AI 拿毒存在误用风险，额外期望加分
                            if(player.countCards('h','du')>0) num+=0.3;
                            if(att==0) num/=2;
                            return num;
                        },
                        target: function(player,target){
                            var att=get.attitude(player,target);
                            var adv=lib.skill.csh_jiaomeng._advantage(player,target);
                            if(adv<=0) return 0;
                            if(att<0) return -Math.min(4,adv/3);
                            if(att>0) return -Math.min(1.5,adv/8);
                            return -Math.min(2,adv/5);
                        },
                    },
                },
                "skill_id": "csh_jiaomeng",
                "_priority": 0,
            },
