                            const dmg = evt.num || 1;
                            const canKill = damaged.hp > 0 && damaged.hp <= dmg + 1;
                            const afterKill = damaged.hp > 0 && damaged.hp <= dmg;
                            // 已能斩杀则不必加伤，留噩摸牌
                            if (afterKill) {
                                if (e >= need2 + 15) return "选项二";
                                return "选项二";
                            }
                            // 加伤可斩或残血压血线
                            if (canKill || damaged.hp <= 2) {
                                if (e >= need2 + 20 && canKill) return "背水！";
                                return "选项一";
                            }
                            // 噩充裕：背水换双收益
                            if (e >= need2 + 25) return "背水！";
                            if (e >= need2 + 15 && me.hp >= 3) return "背水！";
                            // 默认补牌
