            "csh_duwu": {
                priority: 80,

		audio: ["duwu", 2],
		enable: "phaseUse",

		filter(event, player) {

			return game.hasPlayer(function (current) {

				return current.hp > 0 && current.hp <= player.countCards("he") && player.inRange(current);

			});

		},

		filterCard() {

			if (ui.selected.targets.length) {

				return false;

			}

			return true;

		},

		position: "he",

		selectCard: [1, Infinity],

		complexSelect: true,

		complexCard: true,

		filterTarget(card, player, target) {

			return target != player && target.hp > 0 && player.inRange(target) && ui.selected.cards.length == target.hp;

		},

		check(card) {
			var player = _status.event.player;
			if (ui.selected.targets.length) return 0;
			// 找当前最值得打的目标所需牌数
			var bestNeed = 0, bestEff = 0;
			game.countPlayer(function (current) {
				if (current == player || !player.inRange(current) || current.hp <= 0) return;
				var eff = get.damageEffect(current, player, player);
				if (eff <= 0) return;
				// 牌不够打这个目标就跳过
				if (player.countCards("he") < current.hp) return;
				if (eff > bestEff || (eff === bestEff && (bestNeed === 0 || current.hp < bestNeed))) {
					bestEff = eff;
					bestNeed = current.hp;
				}
			});
			if (bestNeed === 0) return 0;
			// 已选够张数就停
			if (ui.selected.cards.length >= bestNeed) return 0;
			var val = get.value(card, player);
			// 优先弃最废的牌
			if (bestNeed === 1) return 12 - val;
			if (bestNeed === 2) return 8 - val;
			if (bestNeed === 3) return 5 - val;
			return 3 - val;
		},

		content() {

			player.addTempSkill("csh_duwu2");

			target.damage("nocard");

		},

		ai: {
			damage: true,
			// 中等偏后：先打常规输出，再考虑弃牌换伤；斩杀时由 result 抬高
			order: 5,
			result: {
				target(player, target) {
					var eff = get.damageEffect(target, player, player);
					if (eff <= 0) return 0;
					// 斩杀窗口（1 血且本次伤害足以使其濒死）大幅加分
					if (target.hp <= 1) eff += 3.5;
					else if (target.hp == 2) eff += 1.2;
					// 弃牌代价：目标体力越高越亏，略降分
					eff -= Math.max(0, target.hp - 1) * 0.35;
					// 自己牌不够或牌质量很高时再由 check 控；此处只评目标
					return eff;
				},
				player(player, target) {
					// 若可能触发自掉血（目标被打到濒死且可能存活），略扣
					if (target.hp <= 1) return -0.8;
					return 0;
				},
			},
			threaten: 1.5,
			expose: 0.3,
		},

	},

