            "csh_twgongxin": {

		audio: ["gongxin", 2],

		enable: "phaseUse",

		filter(event, player) {

			return game.hasPlayer(function (current) {

				return current != player && current.countCards("h");

			});

		},

		filterTarget(card, player, target) {

			return target != player && target.countCards("h") > 0;

		},

		usable: 1,

		async content(event, trigger, player) {

			const { target } = event;

			const cards = target.getCards("h");

			const num = cards.reduce(function (arr, card) {

				arr.add(get.suit(card, player));

				return arr;

			}, []).length;

			const result = await player

				.chooseToMove_new("攻心")

				.set("list", [

					[get.translation(target) + "的手牌", cards],

					[["弃置"], ["置于牌堆顶"]],

				])

				.set("filterOk", moved => {

					return moved[1].slice().concat(moved[2]).length == 1;

				})

				.set("processAI", list => {

					const hand = list[0][1].slice();

					if (!hand.length) return false;

					const suitCount = {};

					for (const c of hand) {

						const s = get.suit(c);

						suitCount[s] = (suitCount[s] || 0) + 1;

					}

					let candidates = hand.filter(c => suitCount[get.suit(c)] === 1);
					if (!candidates.length) candidates = hand.slice();

					candidates.sort((a, b) => {
						const sa = (suitCount[get.suit(a)] === 1 ? 3 : 0) + get.value(a);
						const sb = (suitCount[get.suit(b)] === 1 ? 3 : 0) + get.value(b);
						return sb - sa;
					});
					const card = candidates[0];
					return [hand.slice().remove(card), [card], []];

				})

				.forResult();

			if (result.bool) {

				if (result.moved[1].length) {

					await target.modedDiscard(result.moved[1]);

				} else {

					await player.showCards(result.moved[2], get.translation(player) + "对" + get.translation(target) + "发动了【攻心】");

					await target.lose(result.moved[2], ui.cardPile, "visible", "insert");

				}

				if (

					num >

					target.getCards("h").reduce(function (arr, card) {

						arr.add(get.suit(card, target));

						return arr;

					}, []).length

				) {

					player.line(target);

					player.addTempSkill("csh_twgongxin3", { player: ["twgongxin3After", "phaseAfter"] });

					player.markAuto("csh_twgongxin3", [target]);

				}

			}

		},

		ai: {

			order: 10,

			expose: 0.25,

			result: {

				target(player, target) {

					const att = get.attitude(player, target);
					const hand = target.getCards("h");
					const suits = {};
					for (const c of hand) {
						const s = get.suit(c, target);
						suits[s] = (suits[s] || 0) + 1;
					}
					const unique = Object.values(suits).filter(n => n === 1).length;
					if (att < 0) return -Math.min(6, 1.5 + hand.length * 0.45 + unique * 0.6);
					if (att > 0) return -0.3;
					return -0.6;

				},

			},

		},

	},

