                    if (event.name === "useCard" || event.name === "respond") {
                        return !!(event.cards && event.cards.length);
                    }
                    if (!event.hs || !event.hs.length) return false;
                    // 使用、打出、弃置：手牌进入结算/弃牌堆
                    if (event.type === "use" || event.type === "respond" || event.type === "discard") return true;
                    if (event.position === ui.discardPile) return true;
